#ifndef DAYTONA_NATIVE_HUD_DRAW_H
#define DAYTONA_NATIVE_HUD_DRAW_H
#include "hud.h"
#include "hud_data.h" /* Generated by tools/prepare_hud.py (NATIVE_HUD_DIR). */

/* HUD cells as textured quads in the arcade's 496x384 layout. Pure: the
 * Dreamcast renderer (code/render/ui/hud.c) and the host preview
 * (tests/check_hud.c) both draw exactly this list, sheet by sheet. */
/* The palette bank (after NM_HUD_BANK_FIRST) of a sheet; packs before the gear indicator have one sheet a bank. */
#ifdef NM_HUD_SHEET_BANKS
#define NM_HUD_SHEET_BANK(sheet) ((unsigned)nm_hud_sheet_banks[sheet])
#else
#define NM_HUD_SHEET_BANK(sheet) ((unsigned)(sheet))
#endif
enum { NM_HUD_MAX_QUADS=112+4+NM_HUD_RADAR_CARS+1+6+9+3 }; /* Cells and markers, the gear indicator, the CONDITION panel's icons, nm_hud_overlay_place. */
/* Strip order. sprite, at and turn repeat the placement (nm_hud_tight below). */
typedef struct { float xy[4][2], uv[4][2]; uint8_t sheet, sprite; float at[2], turn[2]; } nm_hud_quad_t;

/* corners: 0 leaves xy and uv unset for the sprites drawn by their tight
 * rectangles (nm_hud_quad_fixed below), which are placed by `at` alone. */
typedef struct { nm_hud_quad_t *quads; unsigned count; int corners; } nm_hud_list_t;

static inline void nm_hud_corners(nm_hud_quad_t *q, const nm_hud_sprite_t *p, float x, float y, float c, float s);
/* Sprite at an element origin; (c,s) turn its offsets as o*c + (J*o)*s. */
static inline void nm_hud_sprite(nm_hud_list_t *list, unsigned sprite, float x, float y, float c, float s) {
    if(sprite>=NM_HUD_SPRITE_COUNT || list->count>=NM_HUD_MAX_QUADS) return;
    const nm_hud_sprite_t *p=nm_hud_sprites+sprite;
    nm_hud_quad_t *q=list->quads+list->count++;
    q->sheet=p->sheet;q->sprite=(uint8_t)sprite;q->at[0]=x;q->at[1]=y;q->turn[0]=c;q->turn[1]=s;
#ifdef NM_HUD_TIGHT
    if(!list->corners && nm_hud_tight[sprite].fixed && c==1.0f && s==0.0f) return;
#endif
    nm_hud_corners(q,p,x,y,c,s);
}
static inline void nm_hud_corners(nm_hud_quad_t *q, const nm_hud_sprite_t *p, float x, float y, float c, float s) {
    const float inverse=1.0f/(float)p->scale;
    const float iw=1.0f/(float)nm_hud_sheets[p->sheet][0],ih=1.0f/(float)nm_hud_sheets[p->sheet][1];
    for(unsigned corner=0;corner<4;++corner) {
        const int dx=(corner&2) ? p->width : 0,dy=(corner&1) ? p->height : 0;
        const float ox=(float)(p->origin_x+dx)*inverse,oy=(float)(p->origin_y+dy)*inverse;
        q->xy[corner][0]=x+ox*c+(nm_hud_map_turn[0][0]*ox+nm_hud_map_turn[0][1]*oy)*s;
        q->xy[corner][1]=y+oy*c+(nm_hud_map_turn[1][0]*ox+nm_hud_map_turn[1][1]*oy)*s;
        q->uv[corner][0]=(float)(p->u+dx)*iw;q->uv[corner][1]=(float)(p->v+dy)*ih;
    }
}
/* A sprite of the table's second part (index >= NM_HUD_TIGHT_EARLY: the rolling start's and the messages'), on whole
 * pixels and never turned, skipped when it lies off the 496 arcade columns. Out of line, as they are: nm_hud_place
 * and nm_hud_tight keep their places in the race's hot layout. */
static __attribute__((noinline, unused)) void nm_hud_late_sprite(nm_hud_list_t *list, unsigned sprite, int x, int y) {
    const nm_hud_sprite_t *p=nm_hud_sprites+sprite;
    if(sprite>=NM_HUD_SPRITE_COUNT || list->count>=NM_HUD_MAX_QUADS) return;
    if(x+p->origin_x>=496 || x+p->origin_x+p->width<=0) return;
    nm_hud_quad_t *q=list->quads+list->count++;
    q->sheet=p->sheet;q->sprite=(uint8_t)sprite;q->at[0]=(float)x;q->at[1]=(float)y;q->turn[0]=1.0f;q->turn[1]=0.0f;
    if(list->corners) nm_hud_corners(q,p,(float)x,(float)y,1.0f,0.0f);
}
/* The map's markers out of line (nm_hud_map_apart): as nm_hud_sprite, for any sprite that turns. */
static __attribute__((noinline, unused)) void nm_hud_late_turned(nm_hud_list_t *list, unsigned sprite, float x, float y, float c, float s) {
    if(sprite>=NM_HUD_SPRITE_COUNT || list->count>=NM_HUD_MAX_QUADS) return;
    const nm_hud_sprite_t *p=nm_hud_sprites+sprite;
    nm_hud_quad_t *q=list->quads+list->count++;
    q->sheet=p->sheet;q->sprite=(uint8_t)sprite;q->at[0]=x;q->at[1]=y;q->turn[0]=c;q->turn[1]=s;
    nm_hud_corners(q,p,x,y,c,s);
}
static inline void nm_hud_cell(nm_hud_list_t *list, unsigned family, unsigned glyph, int x, int y) {
    if(glyph!=NM_HUD_BLANK) nm_hud_sprite(list,family+glyph,(float)x,(float)y,1.0f,0.0f);
}

/* cos/sin of a 16-bit angle are supplied by the caller: SH4 FSCA on the
 * console, libm on the host. */
typedef void (*nm_hud_sincos_t)(uint16_t angle, float *sine, float *cosine);

#ifndef NM_HUD_REVERSE_BLOCK
#error "hud_data.h has no wrong-way message (a818): make the HUD pack again with tools/prepare_hud.py (NATIVE_HUD_DIR)"
#endif
#ifndef NM_HUD_PIT_BLOCK
#error "hud_data.h has no pit message (ab2c): make the HUD pack again with tools/prepare_hud.py (NATIVE_HUD_DIR)"
#endif
#if !defined(NM_HUD_EXTENSION_BLOCK) || !defined(NM_HUD_RADAR)
#error "hud_data.h has no time extension message (ae98) or CONDITION panel: make the HUD pack again with tools/prepare_hud.py (NATIVE_HUD_DIR)"
#endif
/* The CONDITION panel's icons (12c98..13208): each opponent inside the circle at the fitted panel
 * projection of its offset turned by the player's heading, turned itself by its heading minus the
 * player's; the player's icon at the centre, unturned; all scaled with the zoom. The opponents first:
 * their polygons lie behind the player's (depth 1.50003 against 1.49997). */
static inline void nm_hud_radar_place(nm_hud_list_t *list, const nm_hud_t *h, nm_hud_sincos_t sincos) {
    const float k=h->zoom*(1.0f/NM_HUD_RADAR_ZOOM);
    float s0,c0,s,c;
    sincos(h->radar_angle,&s0,&c0);
    for(unsigned i=0;i<h->radar_count && i<NM_HUD_RADAR_CARS;++i) {
        const float dx=h->radar[i].dx*h->zoom,dz=h->radar[i].dz*h->zoom;
        const float f[4]={dx*c0,dx*s0,dz*c0,dz*s0};
        sincos((uint16_t)(h->radar[i].angle-h->radar_angle),&s,&c);
        nm_hud_sprite(list,NM_HUD_RADAR_OPPONENT,
            nm_hud_radar_centre[0]+nm_hud_radar_matrix[0][0]*f[0]+nm_hud_radar_matrix[0][1]*f[1]+
                nm_hud_radar_matrix[0][2]*f[2]+nm_hud_radar_matrix[0][3]*f[3],
            nm_hud_radar_centre[1]+nm_hud_radar_matrix[1][0]*f[0]+nm_hud_radar_matrix[1][1]*f[1]+
                nm_hud_radar_matrix[1][2]*f[2]+nm_hud_radar_matrix[1][3]*f[3],c*k,NM_HUD_RADAR_TURN*s*k);
    }
    nm_hud_sprite(list,NM_HUD_RADAR_PLAYER,nm_hud_radar_centre[0],nm_hud_radar_centre[1],k,0.0f);
}
#ifndef NM_HUD_ROLLING
#error "hud_data.h has no rolling start overlay (ab78, d438): make the HUD pack again with tools/prepare_hud.py (NATIVE_HUD_DIR)"
#endif
#ifndef NM_HUD_SECOND_MARKER
#error "hud_data.h has no second car's marker (12b34): make the HUD pack again with tools/prepare_hud.py --second-marker (NATIVE_HUD_DIR)"
#endif
#ifndef NM_HUD_LAP_MESSAGE
#error "hud_data.h has no lap message (ad34): make the HUD pack again with tools/prepare_hud.py (NATIVE_HUD_DIR)"
#endif
/* The car of the banner on the screen: column 0 of the tile layer in the 1024-pixel ring, as -512..511; the car and
 * the banner lie within the ring's first 512 pixels, so one place shows all of them. */
static inline int nm_hud_roll_x(const nm_hud_t *h) { return (int)((1536u-h->roll_scroll)&1023u)-512; }
/* The map and its markers out of line, for all but course 0's plain case (nm_hud_place): nm_hud_place stays what it was.
 * At another size than the default (the chord, nm_hud_overlay; k = the scale against the default) its polygons and the
 * marker places scale about the projected origin of its model, the constant of the leader's matrix (height 0), and
 * the markers keep their size; one whole quad for the map, on whole pixels only at k = 1. The largest size reaches the
 * CONDITION label: on course 0 the map's sheet is the label's and the two swap places, as tiles over polygons; the
 * other courses' maps lie on a later sheet and paint over the label's top row.
 * Another course's map turns the markers by its model's angle, and its depth sizes them (turn, size; 12a10..12af0).
 * While the player leads the second car carries the "2" 288b5f0 (12b34), under the player's marker, whose copy
 * MARKER_TOP lies on its sheet. */
static __attribute__((noinline, unused)) void nm_hud_map_apart(nm_hud_list_t *list, const nm_hud_t *h, nm_hud_sincos_t sincos) {
    const nm_hud_course_map_t *m=h->course<3 && nm_hud_course_maps[h->course].player ? nm_hud_course_maps+h->course : 0;
    if(!m) return;
    const float (*leader)[3]=m->leader,(*player)[3]=m->player;
    const float ax=leader[0][2],ay=leader[1][2],standard=nm_force_float(nm_hud_map_scales[h->course][1]);
    const float k=h->map_scale==standard ? 1.0f : h->map_scale*(1.0f/standard);
    float s,c;
    if(k==1.0f) nm_hud_sprite(list,m->sprite,(float)m->x,(float)m->y,1.0f,0.0f);
    else {
        nm_hud_sprite(list,m->sprite,ax+k*((float)m->x-ax),ay+k*((float)m->y-ay),k,0.0f);
        for(unsigned i=0;i+1<list->count;++i) if(list->quads[i].sprite==NM_HUD_CONDITION_LABEL) {
            nm_hud_quad_t q;
            nm_memcpy(&q,list->quads+i,sizeof(q));nm_memcpy(list->quads+i,list->quads+list->count-1,sizeof(q));
            nm_memcpy(list->quads+list->count-1,&q,sizeof(q));
            break;
        }
    }
    if(h->leader) {
        sincos((uint16_t)(h->leader_yaw+m->turn),&s,&c);
        nm_hud_late_turned(list,h->leader_second ? NM_HUD_MARKER_SECOND : NM_HUD_MARKER_LEADER,
            ax+k*(leader[0][0]*h->leader_x+leader[0][1]*h->leader_z),ay+k*(leader[1][0]*h->leader_x+leader[1][1]*h->leader_z),
            c*m->size,s*m->size);
    }
    sincos((uint16_t)(h->player_yaw+m->turn),&s,&c);
    nm_hud_late_turned(list,h->leader_second ? NM_HUD_MARKER_TOP : NM_HUD_MARKER_PLAYER,
        ax+k*(player[0][0]*h->player_x+player[0][1]*h->player_z+player[0][2]-ax),
        ay+k*(player[1][0]*h->player_x+player[1][1]*h->player_z+player[1][2]-ay),c*m->size,s*m->size);
}
/* nm_hud_overlay's elements. Tile layer 0 lies over the map's polygons, as the paint order here. */
static __attribute__((noinline, unused)) void nm_hud_overlay_place(nm_hud_list_t *list, const nm_hud_t *h, nm_hud_sincos_t sincos) {
    if(h->map_apart && h->map) nm_hud_map_apart(list,h,sincos);
    if(h->roll_banner) {
        const int x=nm_hud_roll_x(h);
        nm_hud_late_sprite(list,NM_HUD_ROLL_CAR,x+NM_HUD_ROLL_CAR_X,NM_HUD_ROLL_CAR_Y);
        nm_hud_late_sprite(list,NM_HUD_ROLL_BANNER_0,x+NM_HUD_ROLL_BANNER_0_X,NM_HUD_ROLL_BANNER_0_Y);
        nm_hud_late_sprite(list,NM_HUD_ROLL_BANNER_1,x+NM_HUD_ROLL_BANNER_1_X,NM_HUD_ROLL_BANNER_1_Y);
    }
    if(h->roll_hint==1) nm_hud_late_sprite(list,NM_HUD_ROLL_ACCEL,NM_HUD_ROLL_ACCEL_X,NM_HUD_ROLL_ACCEL_Y);
    if(h->roll_hint==2) nm_hud_late_sprite(list,NM_HUD_ROLL_AUTO,NM_HUD_ROLL_AUTO_X,NM_HUD_ROLL_AUTO_Y);
    if(h->roll_digit) nm_hud_late_sprite(list,NM_HUD_ROLL_DIGIT_1+h->roll_digit-1u,NM_HUD_ROLL_DIGIT_X,NM_HUD_ROLL_DIGIT_Y);
    if(h->roll_go) nm_hud_late_sprite(list,NM_HUD_ROLL_GO,NM_HUD_ROLL_GO_X,NM_HUD_ROLL_GO_Y);
    if(h->lap_label) {
        uint8_t cells[8];
        nm_hud_time(h->lap_time,cells);
        nm_hud_late_sprite(list,h->lap_label==2 ? NM_HUD_MSG_BEST : NM_HUD_MSG_LAP,NM_HUD_MSG_LABEL_X,NM_HUD_MSG_LABEL_Y);
        for(unsigned i=0;i<8;++i) if(cells[i]!=NM_HUD_BLANK)
            nm_hud_late_sprite(list,NM_HUD_MSG_0+cells[i],NM_HUD_MSG_TIME_X+16*(int)i,NM_HUD_MSG_TIME_Y);
    }
}
/* The panel under the icons: a stipple of one colour in the original, one translucent rectangle here
 * (x0, y0, x1, y1 in arcade pixels, colour NM_HUD_RADAR_PANEL_ARGB) behind every HUD sprite, drawn
 * with the map. Returns 1 when it is shown. */
static inline int nm_hud_radar_panel_rect(const nm_hud_t *h, float rect[4]) {
    if(!h->map) return 0;
    for(unsigned i=0;i<4;++i) rect[i]=nm_hud_radar_panel[i];
    return 1;
}
/* b0c0: the lever, or the digit between its brackets with the label below. A pack made before the gear
 * indicator (no NM_HUD_GEAR) draws nothing. Out of line, one placement loop: nm_hud_place (the race's
 * nm_hud_render_enqueue) grows by a call.
 * NM_HUD_GEAR_DIGIT (include/hud.h; with the gate): the digit of "(n)" (8x15, yellow, black outline) with
 * the lever, its cell's top left at NM_HUD_GEAR_DIGIT_AT_X/Y: to the right of the gate, 3 pixels from its
 * art (columns 297..304 against the gate's 274..293), centred on it (rows 76..90 against 73..92). Clear of
 * the km/h readout (to 263), the arc's "10" (from 310) and ae98's "TIME EXTENSION!!" (rows 96..111 at row
 * 12, 128.. at row 16). The needle's inner end (radius 121 from the pivot) crosses the cell from about
 * 8200 rpm to the stop (0x2134); it is placed before the indicator (nm_hud_place), so the digit (same sheet,
 * later) and the gate (a later sheet) lie over it. */
#ifdef NM_HUD_GEAR
#if NM_HUD_GEAR_DIGIT==1
#ifndef NM_HUD_GEAR_DIGIT_AT_X
#define NM_HUD_GEAR_DIGIT_AT_X (NM_HUD_GEAR_LEVER_X+25)
#endif
#ifndef NM_HUD_GEAR_DIGIT_AT_Y
#define NM_HUD_GEAR_DIGIT_AT_Y (NM_HUD_GEAR_LEVER_Y+4)
#endif
#elif NM_HUD_GEAR_DIGIT
#error "NM_HUD_GEAR_DIGIT must be 0 or 1"
#endif
static __attribute__((noinline, unused)) void nm_hud_gear_place(nm_hud_list_t *list, const nm_hud_t *h) {
    struct { uint16_t sprite, x, y; } item[4];
    unsigned n=0;
    if(h->gear_lever<=6) {
        item[n].sprite=(uint16_t)(NM_HUD_GEAR_LEVER_0+h->gear_lever);item[n].x=NM_HUD_GEAR_LEVER_X;item[n++].y=NM_HUD_GEAR_LEVER_Y;
#if NM_HUD_GEAR_DIGIT
        if(h->gear_digit>=1 && h->gear_digit<=4) {
            item[n].sprite=(uint16_t)(NM_HUD_GEAR_DIGIT_1+h->gear_digit-1u);
            item[n].x=NM_HUD_GEAR_DIGIT_AT_X;item[n++].y=NM_HUD_GEAR_DIGIT_AT_Y;
        }
#endif
    } else if(h->gear_digit>=1 && h->gear_digit<=4) {
        item[0].sprite=NM_HUD_GEAR_OPEN;item[0].x=NM_HUD_GEAR_LEVER_X;item[0].y=NM_HUD_GEAR_LEVER_Y;
        item[1].sprite=(uint16_t)(NM_HUD_GEAR_DIGIT_1+h->gear_digit-1u);item[1].x=NM_HUD_GEAR_DIGIT_X;item[1].y=NM_HUD_GEAR_DIGIT_Y;
        item[2].sprite=NM_HUD_GEAR_CLOSE;item[2].x=NM_HUD_GEAR_CLOSE_X;item[2].y=NM_HUD_GEAR_CLOSE_Y;
        item[3].sprite=NM_HUD_GEAR_LABEL;item[3].x=NM_HUD_GEAR_LABEL_X;item[3].y=NM_HUD_GEAR_LABEL_Y;
        n=4;
    }
    for(unsigned i=0;i<n;++i) nm_hud_sprite(list,item[i].sprite,(float)item[i].x,(float)item[i].y,1.0f,0.0f);
}
#endif
static inline unsigned nm_hud_place(const nm_hud_t *h, nm_hud_quad_t quads[NM_HUD_MAX_QUADS], nm_hud_sincos_t sincos, int corners) {
    nm_hud_list_t list={quads,0,corners};
    float s,c;
    nm_hud_sprite(&list,NM_HUD_TACH,NM_HUD_TACH_X,NM_HUD_TACH_Y,1,0);
    if(h->map) nm_hud_radar_place(&list,h,sincos); /* Under the frame (tiles cover the original's polygons). */
    nm_hud_sprite(&list,NM_HUD_LAP_LABEL,NM_HUD_LAP_LABEL_X,NM_HUD_LAP_LABEL_Y,1,0);
    nm_hud_sprite(&list,NM_HUD_POSITION_LABEL,NM_HUD_POSITION_LABEL_X,NM_HUD_POSITION_LABEL_Y,1,0);
    nm_hud_sprite(&list,NM_HUD_CONDITION_FRAME,NM_HUD_CONDITION_FRAME_X,NM_HUD_CONDITION_FRAME_Y,1,0);
    nm_hud_sprite(&list,NM_HUD_CONDITION_LABEL,NM_HUD_CONDITION_LABEL_X,NM_HUD_CONDITION_LABEL_Y,1,0);
    for(unsigned i=0;i<2;++i) nm_hud_cell(&list,NM_HUD_TIMER_0,h->timer[i],NM_HUD_TIMER_X+24*(int)i,NM_HUD_TIMER_Y);
    if(h->lap_current>=1 && h->lap_current<=8)
        nm_hud_cell(&list,NM_HUD_CIRCLE_1,h->lap_current-1u,NM_HUD_CIRCLE_CURRENT_X,NM_HUD_CIRCLE_CURRENT_Y);
    nm_hud_sprite(&list,NM_HUD_CIRCLE_11,NM_HUD_CIRCLE_SLASH_X,NM_HUD_CIRCLE_SLASH_Y,1,0);
    if(h->lap_total>=1 && h->lap_total<=8)
        nm_hud_cell(&list,NM_HUD_CIRCLE_1,h->lap_total-1u,NM_HUD_CIRCLE_TOTAL_X,NM_HUD_CIRCLE_TOTAL_Y);
    for(unsigned row=0;row<h->rows && row<8;++row) {
        const nm_hud_lap_row_t *lap=h->lap+row;
        const int y=NM_HUD_LAP_ROW_Y+16*(int)row;
        for(unsigned i=0;i<2;++i) nm_hud_cell(&list,NM_HUD_LAPNUM_0,lap->number[i],NM_HUD_LAP_NUMBER_X+8*(int)i,y);
        for(unsigned i=0;i<8;++i)
            nm_hud_cell(&list,lap->best ? NM_HUD_BEST_0 : NM_HUD_TIME_0,lap->time[i],NM_HUD_LAP_TIME_X+8*(int)i,y);
    }
    if(h->rank_drawn) {
        for(unsigned i=0;i<2;++i) nm_hud_cell(&list,NM_HUD_BIG_0,h->rank[i],NM_HUD_RANK_X+16*(int)i,NM_HUD_RANK_Y);
        nm_hud_cell(&list,NM_HUD_BIG_0,h->suffix,NM_HUD_SUFFIX_X,NM_HUD_SUFFIX_Y);
    }
    nm_hud_sprite(&list,NM_HUD_BIG_SLASH,NM_HUD_SLASH_X,NM_HUD_SLASH_Y,1,0);
    for(unsigned i=0;i<2;++i) nm_hud_cell(&list,NM_HUD_BIG_0,h->count[i],NM_HUD_COUNT_X+16*(int)i,NM_HUD_COUNT_Y);
    if(h->speed_drawn) {
        for(unsigned i=0;i<3;++i) nm_hud_cell(&list,NM_HUD_SPEED_0,h->speed[i],NM_HUD_SPEED_X+16*(int)i,NM_HUD_SPEED_Y);
        nm_hud_sprite(&list,NM_HUD_SPEED_UNIT,NM_HUD_UNIT_X,NM_HUD_UNIT_Y,1,0);
    }
    if(h->reverse) nm_hud_sprite(&list,NM_HUD_REVERSE,NM_HUD_REVERSE_X,NM_HUD_REVERSE_Y,1,0);
    if(h->extension&1u) nm_hud_sprite(&list,NM_HUD_EXTENSION,NM_HUD_EXTENSION_X,NM_HUD_EXTENSION_Y,1,0);
    if(h->extension&2u) nm_hud_sprite(&list,NM_HUD_EXTENSION,NM_HUD_EXTENSION_LOW_X,NM_HUD_EXTENSION_LOW_Y,1,0);
    if(h->pit) nm_hud_sprite(&list,NM_HUD_PIT,NM_HUD_PIT_X,NM_HUD_PIT_Y,1,0);
    /* The course's map (prepare_hud.py nm_hud_course_maps: course 0's, and --course-map's); none without one.
     * Here course 0's at the default size; everything else nm_hud_map_apart. */
    const nm_hud_course_map_t *course_map=h->course<3 && nm_hud_course_maps[h->course].player ? nm_hud_course_maps+h->course : 0;
    if(h->map && course_map && !h->map_apart) {
        const float (*leader)[3]=course_map->leader,(*player)[3]=course_map->player;
        nm_hud_sprite(&list,course_map->sprite,course_map->x,course_map->y,1,0);
        if(h->leader) {
            sincos(h->leader_yaw,&s,&c);
            nm_hud_sprite(&list,NM_HUD_MARKER_LEADER,
                leader[0][0]*h->leader_x+leader[0][1]*h->leader_z+leader[0][2],
                leader[1][0]*h->leader_x+leader[1][1]*h->leader_z+leader[1][2],c,s);
        }
        sincos(h->player_yaw,&s,&c);
        nm_hud_sprite(&list,NM_HUD_MARKER_PLAYER,
            player[0][0]*h->player_x+player[0][1]*h->player_z+player[0][2],
            player[1][0]*h->player_x+player[1][1]*h->player_z+player[1][2],c,s);
    }
    if(h->needle && list.count<NM_HUD_MAX_QUADS) {
        static const uint8_t strip[4]={0,1,3,2}; /* Model perimeter order to strip order. */
        const nm_hud_sprite_t *p=nm_hud_sprites+NM_HUD_NEEDLE;
        nm_hud_quad_t *q=quads+list.count++;
        sincos(h->needle_angle,&s,&c);
        q->sheet=p->sheet;q->sprite=NM_HUD_NEEDLE;q->at[0]=q->at[1]=q->turn[0]=q->turn[1]=0;
        for(unsigned corner=0;corner<4;++corner) {
            const unsigned k=strip[corner];
            q->xy[corner][0]=nm_hud_needle_pivot[0]+nm_hud_needle_cos[k][0]*c+nm_hud_needle_sin[k][0]*s;
            q->xy[corner][1]=nm_hud_needle_pivot[1]+nm_hud_needle_cos[k][1]*c+nm_hud_needle_sin[k][1]*s;
            q->uv[corner][0]=((float)p->u+0.5f*(float)p->width)/(float)nm_hud_sheets[p->sheet][0];
            q->uv[corner][1]=((float)p->v+0.5f*(float)p->height)/(float)nm_hud_sheets[p->sheet][1];
        }
    }
    /* After the needle: the gear digit shares its sheet and lies over it where it crosses (as the arcade's
     * tiles cover its polygon); the gate's sheet is painted later still. */
#ifdef NM_HUD_GEAR
    if(h->gear_lever<=6 || h->gear_digit) nm_hud_gear_place(&list,h);
#endif
    if(h->overlay) nm_hud_overlay_place(&list,h,sincos);
    return list.count;
}
static inline unsigned nm_hud_quads(const nm_hud_t *h, nm_hud_quad_t quads[NM_HUD_MAX_QUADS], nm_hud_sincos_t sincos) {
    return nm_hud_place(h,quads,sincos,1);
}

/* ---- Tight geometry -------------------------------------------------------
 * What the PVR is given instead of one punch-through quad a sprite. Every
 * pixel of a punch-through polygon is textured for the alpha test, the
 * transparent ones for nothing, and two thirds of the HUD's were transparent
 * (the tachometer, the condition frame and the map are 78 to 90% empty). But
 * every rectangle is also SH4 work (TA records through the store queues), and
 * the SH4 is the binding limit in the race's worst frames. So the packer
 * (tools/prepare_hud.py, tight_pieces, CostModel) draws each sprite either as
 * its one rectangle or as
 *   cores:  rectangles without a transparent texel, for the opaque list: the
 *           hidden-surface pass resolves them before anything is textured,
 *           and they hide the 3D picture and the sprite's own pieces behind;
 *   pieces: punch-through rectangles holding every other opaque texel,
 * whichever costs less in its model of SH4 and PVR time. A sprite drawn whole
 * has one rectangle: a core when it has no transparent texel, else a piece.
 * Same sheets, same texels, same pixels: a rectangle's corners are its texel
 * boundaries placed by the expression of nm_hud_sprite (nm_hud_span below),
 * so it maps texels to pixels exactly as the whole quad did.
 *
 * Paint order becomes depth. The whole quads were drawn without a depth test
 * in sheet order, later over earlier. Now the sprite of paint rank r lies at
 * NM_HUD_DEPTH+2r and its cores one nearer, in front of the 3D picture (1/z
 * up to 100 at the near plane 0.01, times a layer step below 1.25). `flat`
 * (nm_hud_render_enqueue) submits the same rectangles in paint order on the
 * punch-through list without a depth test, as the quads were, for frames
 * that hold another overlay drawn that way.
 *
 * Rows. 480/384 = 5/4 puts the centre of every fifth output row exactly on a
 * boundary between two texel rows; which of them a whole quad showed there
 * was left to the rounding of the PVR's interpolation, and a core must never
 * sample the transparent texel beyond its edge. Sprites on whole arcade
 * pixels are therefore drawn NM_HUD_ROW_NUDGE of an output pixel higher:
 * every row centre is then at least an eighth of a pixel inside its texel
 * row, the one a sampler that rounds down takes at the boundary (the rule of
 * tools/check_hud.py and tests/check_hud_tight.c), and no edge crosses a row
 * centre. Columns need nothing: 640/496 = 40/31 leaves every column centre
 * at least 1/62 pixel from a texel boundary. The markers, the CONDITION
 * panel's car icons and the needle turn and move freely; they keep their one
 * quad, vertex for vertex (the icons have no transparent texel: opaque). */
#ifndef NM_HUD_TIGHT
#error "hud_data.h has no tight geometry: make the HUD pack again with tools/prepare_hud.py (NATIVE_HUD_DIR)"
#endif
enum { NM_HUD_MAX_PIECES=288 }; /* 18 KiB of TA records as sprites (36 KiB as strips); the reserve beside the 3D stream is 64 KiB (model_renderer.c). */
#define NM_HUD_DEPTH 256.0f
#define NM_HUD_ROW_NUDGE 0.125f
typedef struct { float xy[4][2], uv[4][2], z; uint8_t sheet, opaque; } nm_hud_piece_t; /* Output pixels, strip order. */

/* A rectangle r (x, y, width, height in texels) of a sprite: its edges as
 * offsets from the element origin in arcade pixels, and as sheet coordinates.
 * Static: the console computes these once at load (code/render/ui/hud_render.c). */
typedef struct { float x[2], y[2], u[2], v[2]; } nm_hud_span_t;
static inline nm_hud_span_t nm_hud_span(unsigned sprite, const uint8_t r[4]) {
    const nm_hud_sprite_t *p=nm_hud_sprites+sprite;
    const float inverse=1.0f/(float)p->scale;
    const float iw=1.0f/(float)nm_hud_sheets[p->sheet][0],ih=1.0f/(float)nm_hud_sheets[p->sheet][1];
    nm_hud_span_t s;
    for(unsigned edge=0;edge<2;++edge) {
        const int dx=r[0]+(edge ? r[2] : 0),dy=r[1]+(edge ? r[3] : 0);
        s.x[edge]=(float)(p->origin_x+dx)*inverse;s.y[edge]=(float)(p->origin_y+dy)*inverse;
        s.u[edge]=(float)(p->u+dx)*iw;s.v[edge]=(float)(p->v+dy)*ih;
    }
    return s;
}
/* A span of a fixed quad (on whole arcade pixels, not turned) at the quad's
 * element origin in output pixels: left, right, top, bottom. For such a quad
 * nm_hud_sprite's expression at + o*c + (J*o)*s is at + o exactly. */
static inline void nm_hud_span_place(const nm_hud_span_t *span, const float at[2], float sx, float sy, float out[4]) {
    out[0]=(at[0]+span->x[0])*sx;out[1]=(at[0]+span->x[1])*sx;
    out[2]=(at[1]+span->y[0])*sy-NM_HUD_ROW_NUDGE;out[3]=(at[1]+span->y[1])*sy-NM_HUD_ROW_NUDGE;
}

static inline int nm_hud_quad_fixed(const nm_hud_quad_t *q) {
    return NM_HUD_TIGHT_OF(q->sprite)->fixed && q->turn[0]==1.0f && q->turn[1]==0.0f;
}
/* Rectangles of a quad when sprites below `level` are drawn whole. */
static inline unsigned nm_hud_quad_pieces(const nm_hud_quad_t *q, unsigned level) {
    const nm_hud_tight_t *t=NM_HUD_TIGHT_OF(q->sprite);
    return nm_hud_quad_fixed(q) && t->priority>=level ? (unsigned)t->cores+t->pieces : 1u;
}

/* quads: nm_hud_quads' list. sx, sy: output pixels per arcade pixel. Returns
 * the rectangles in paint order (sheet by sheet as before, a sprite's cores
 * before its pieces); never more than NM_HUD_MAX_PIECES: a frame that would
 * need more draws the sprites that gain least as whole quads again. */
static inline unsigned nm_hud_tight_pieces(const nm_hud_quad_t *quads, unsigned count,
        nm_hud_piece_t out[NM_HUD_MAX_PIECES], float sx, float sy) {
    _Static_assert((int)NM_HUD_MAX_PIECES>=(int)NM_HUD_MAX_QUADS,"every sprite as one quad must fit");
    unsigned level=0,total=0,rank=0;
    for(;;) {
        unsigned need=0;
        for(unsigned i=0;i<count;++i) need+=nm_hud_quad_pieces(quads+i,level);
        if(need<=NM_HUD_MAX_PIECES) break;
        level+=8; /* 256: every sprite whole, at most NM_HUD_MAX_QUADS. */
    }
    for(unsigned sheet=0;sheet<NM_HUD_SHEET_COUNT;++sheet) for(unsigned i=0;i<count;++i) {
        const nm_hud_quad_t *q=quads+i;
        if(q->sheet!=sheet) continue;
        const nm_hud_tight_t *t=NM_HUD_TIGHT_OF(q->sprite);
        const float z=NM_HUD_DEPTH+2.0f*(float)rank++;
        if(!nm_hud_quad_fixed(q)) { /* One quad as it was; opaque when the sprite has no transparent texel (one core alone). */
            nm_hud_piece_t *o=out+total++;
            for(unsigned corner=0;corner<4;++corner) {
                o->xy[corner][0]=q->xy[corner][0]*sx;o->xy[corner][1]=q->xy[corner][1]*sy;
                o->uv[corner][0]=q->uv[corner][0];o->uv[corner][1]=q->uv[corner][1];
            }
            o->sheet=q->sheet;o->opaque=t->cores==1 && !t->pieces;o->z=z+(float)o->opaque;
            continue;
        }
        const nm_hud_sprite_t *p=nm_hud_sprites+q->sprite;
        const unsigned whole=t->priority<level,n=whole ? 1u : (unsigned)t->cores+t->pieces;
        for(unsigned k=0;k<n;++k) {
            const uint8_t full[4]={0,0,p->width,p->height},*r=whole ? full : nm_hud_rectangles[t->first+k];
            const nm_hud_span_t span=nm_hud_span(q->sprite,r);
            float edge[4];nm_hud_span_place(&span,q->at,sx,sy,edge);
            nm_hud_piece_t *o=out+total++;
            o->sheet=q->sheet;o->opaque=!whole && k<t->cores;o->z=z+(float)o->opaque;
            for(unsigned corner=0;corner<4;++corner) {
                o->xy[corner][0]=edge[corner>>1];o->xy[corner][1]=edge[2+(corner&1)];
                o->uv[corner][0]=span.u[corner>>1];o->uv[corner][1]=span.v[corner&1];
            }
        }
    }
    return total;
}

/* Sprite records carry u and v as the upper 16 bits of their floats
 * (PVR_UVFMT_16BIT): 8 significant bits. Every texel boundary of a sheet of
 * at most 256 texels (an integer up to 256 over a power of two) fits, and so
 * does the needle's texel centre; returns 1 when every coordinate the HUD
 * submits is exact so. */
static inline int nm_hud_uv16_exact(float value) {
    uint32_t bits;__builtin_memcpy(&bits,&value,4);return (bits&0xffffu)==0;
}
static inline int nm_hud_uv16_valid(void) {
    for(unsigned sprite=0;sprite<NM_HUD_SPRITE_COUNT;++sprite) {
        const nm_hud_sprite_t *p=nm_hud_sprites+sprite;
        const nm_hud_tight_t *t=NM_HUD_TIGHT_OF(sprite);
        const uint8_t full[4]={0,0,p->width,p->height};
        for(unsigned k=0;k<=(unsigned)t->cores+t->pieces;++k) {
            if(k<(unsigned)t->cores+t->pieces && t->first+k>=NM_HUD_RECTANGLE_COUNT) return 0;
            const nm_hud_span_t s=nm_hud_span(sprite,k<(unsigned)t->cores+t->pieces ? nm_hud_rectangles[t->first+k] : full);
            for(unsigned e=0;e<2;++e) if(!nm_hud_uv16_exact(s.u[e]) || !nm_hud_uv16_exact(s.v[e])) return 0;
        }
        /* The needle samples its texel centre (nm_hud_quads). */
        if(sprite==NM_HUD_NEEDLE && (!nm_hud_uv16_exact(((float)p->u+0.5f*(float)p->width)/(float)nm_hud_sheets[p->sheet][0]) ||
           !nm_hud_uv16_exact(((float)p->v+0.5f*(float)p->height)/(float)nm_hud_sheets[p->sheet][1]))) return 0;
    }
    return 1;
}

/* Texel index of a twiddled PAL4 sheet (payload after the 32-byte header). */
static inline unsigned nm_hud_sheet_texel(const uint8_t *payload, unsigned width, unsigned height, unsigned x, unsigned y) {
    const unsigned side=width<height ? width : height;
    unsigned index=(x/side+y/side)*side*side;
    for(unsigned bit=0;(1u<<bit)<side;++bit) index|=((y>>bit)&1u)<<(2*bit) | ((x>>bit)&1u)<<(2*bit+1);
    return (payload[index/2]>>(index&1u ? 4 : 0))&15u;
}
/* The tight table against the texels of one sheet: every rectangle inside its
 * sprite, no transparent texel in a core, no opaque texel of a sprite outside
 * its rectangles. palette: the sheet's 16 ARGB8888 colours (opaque: alpha of
 * 128 or more). marks: scratch of NM_HUD_MARK_BYTES. Returns 1 when it holds. */
enum { NM_HUD_MARK_BYTES=256*256/8 };
static inline int nm_hud_tight_valid(unsigned sheet, const uint8_t *payload, const uint32_t palette[16], uint8_t *marks) {
    const unsigned sw=nm_hud_sheets[sheet][0],sh=nm_hud_sheets[sheet][1];
    for(unsigned sprite=0;sprite<NM_HUD_SPRITE_COUNT;++sprite) {
        const nm_hud_sprite_t *p=nm_hud_sprites+sprite;
        const nm_hud_tight_t *t=NM_HUD_TIGHT_OF(sprite);
        if(p->sheet!=sheet) continue;
        const unsigned n=(unsigned)t->cores+t->pieces;
        if(!n || t->first+n>NM_HUD_RECTANGLE_COUNT || p->u+p->width>sw || p->v+p->height>sh) return 0;
        if(!t->fixed && (n!=1 || nm_hud_rectangles[t->first][2]!=p->width || nm_hud_rectangles[t->first][3]!=p->height)) return 0;
        for(unsigned i=0;i<((unsigned)p->width*p->height+7u)/8u;++i) marks[i]=0;
        for(unsigned k=0;k<n;++k) {
            const uint8_t *r=nm_hud_rectangles[t->first+k];
            if(!r[2] || !r[3] || r[0]+r[2]>p->width || r[1]+r[3]>p->height) return 0;
            for(unsigned y=r[1];y<(unsigned)r[1]+r[3];++y) for(unsigned x=r[0];x<(unsigned)r[0]+r[2];++x) {
                if(k<t->cores && palette[nm_hud_sheet_texel(payload,sw,sh,p->u+x,p->v+y)]>>24<128u) return 0;
                marks[(y*p->width+x)/8u]|=(uint8_t)(1u<<((y*p->width+x)&7u));
            }
        }
        for(unsigned y=0;y<p->height;++y) for(unsigned x=0;x<p->width;++x)
            if(palette[nm_hud_sheet_texel(payload,sw,sh,p->u+x,p->v+y)]>>24>=128u &&
               !(marks[(y*p->width+x)/8u]>>((y*p->width+x)&7u)&1u)) return 0;
    }
    return 1;
}
#endif
